INSERT INTO `protection_drill_question_details` VALUES (1, 3, 48, '强制社交识别', '这种要求可能存在什么问题？', 1, '强制社交', 1, '强制社交', 1, 10, '你正确识别了这个风险信号！应该明确设定个人边界', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '继续加油！每道题都是学习的机会。', '[{\"id\": 1, \"text\": \"强制社交\", \"is_correct\": true, \"description\": \"强迫参与不当社交活动\", \"is_selected\": true}, {\"id\": 2, \"text\": \"工作需要\", \"is_correct\": false, \"description\": \"工作必需的社交\", \"is_selected\": false}, {\"id\": 3, \"text\": \"团队建设\", \"is_correct\": false, \"description\": \"团队建设活动\", \"is_selected\": false}]', 1, '2025-10-10 17:48:31');
