INSERT INTO `protection_drill_question_details` VALUES (6, 3, 44, '工作成果抢夺', '这种行为属于什么性质？', 3, '谦虚表现', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '继续加油！每道题都是学习的机会。', '[{\"id\": 1, \"text\": \"成果盗取\", \"is_correct\": true, \"description\": \"冒领他人的工作成果\", \"is_selected\": false}, {\"id\": 2, \"text\": \"团队合作\", \"is_correct\": false, \"description\": \"强调团队协作\", \"is_selected\": false}, {\"id\": 3, \"text\": \"谦虚表现\", \"is_correct\": false, \"description\": \"谦虚的工作态度\", \"is_selected\": true}]', 6, '2025-10-10 17:48:32');
INSERT INTO `protection_drill_question_details` VALUES (7, 3, 36, '职场歧视识别', '这种提问存在什么问题？', 2, '正常询问', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '继续加油！每道题都是学习的机会。', '[{\"id\": 1, \"text\": \"性别歧视\", \"is_correct\": true, \"description\": \"基于性别的就业歧视\", \"is_selected\": false}, {\"id\": 2, \"text\": \"正常询问\", \"is_correct\": false, \"description\": \"了解员工稳定性\", \"is_selected\": true}, {\"id\": 3, \"text\": \"关心表现\", \"is_correct\": false, \"description\": \"对员工的关心\", \"is_selected\": false}]', 7, '2025-10-10 17:48:32');
INSERT INTO `protection_drill_question_details` VALUES (8, 3, 40, '言语骚扰识别', '这种言论属于什么性质？', 2, '普通聊天', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '继续加油！每道题都是学习的机会。', '[{\"id\": 1, \"text\": \"言语骚扰\", \"is_correct\": true, \"description\": \"基于性别的歧视性言论\", \"is_selected\": false}, {\"id\": 2, \"text\": \"普通聊天\", \"is_correct\": false, \"description\": \"同事间的日常聊天\", \"is_selected\": true}, {\"id\": 3, \"text\": \"关心询问\", \"is_correct\": false, \"description\": \"对同事的关心\", \"is_selected\": false}]', 8, '2025-10-10 17:48:32');
INSERT INTO `protection_drill_question_details` VALUES (9, 4, 52, '网络欺凌识别', '这种行为属于什么类型的问题？', 2, '普通聊天', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你的选择反映出可能对情感操控的隐蔽性还不够敏感，这很正常，很多人一开始也容易忽视。这次题目提醒我们：当有人用“分手”来威胁你断绝正常社交时，这已不是普通聊天，而是越界的情感控制。关键要记住：健康的关系尊重个人边界。今后遇到类似情况，试着冷静回应：“我理解你的感受，但我的朋友对我来说很重要，我们可以一起沟通，不必用分开来解决问题。”建议你多关注情感操控的常见话术，提升觉察能力。你已经在进步的路上，继续加油！', '[{\"id\": 1, \"text\": \"网络欺凌\", \"is_correct\": true, \"description\": \"在网络平台上恶意传播和攻击\", \"is_selected\": false}, {\"id\": 2, \"text\": \"普通聊天\", \"is_correct\": false, \"description\": \"同学间的日常交流\", \"is_selected\": true}, {\"id\": 3, \"text\": \"开玩笑\", \"is_correct\": false, \"description\": \"只是开个小玩笑\", \"is_selected\": false}]', 1, '2025-10-10 19:09:05');
INSERT INTO `protection_drill_question_details` VALUES (10, 4, 54, '校园暴力识别', '这种威胁属于什么性质？', 2, '同学冲突', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你选择“同学冲突”说明你在积极思考人际关系的性质，这很好！但这次的情况更接近情感操控，关键是要识别出“以分手相逼”是一种越界行为。学习重点是：设定清晰的个人边界，不因恐惧或压力妥协社交自由。现实中，若有人用情绪威胁控制你，要冷静表达底线，比如：“我可以自己决定和谁做朋友。”建议你多关注关系中的“是否被尊重”，练习坚定而温和地表达需求，这是保护自己的重要能力。继续加油，你已经在成长的路上了！', '[{\"id\": 1, \"text\": \"校园暴力\", \"is_correct\": true, \"description\": \"使用暴力威胁的恶性行为\", \"is_selected\": false}, {\"id\": 2, \"text\": \"同学冲突\", \"is_correct\": false, \"description\": \"普通的同学矛盾\", \"is_selected\": true}, {\"id\": 3, \"text\": \"开玩笑\", \"is_correct\": false, \"description\": \"年龄差异的玩笑\", \"is_selected\": false}]', 2, '2025-10-10 19:09:10');
INSERT INTO `protection_drill_question_details` VALUES (11, 5, 52, '网络欺凌识别', '这种行为属于什么类型的问题？', 2, '普通聊天', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你选择“普通聊天”说明你可能倾向于往善意方向理解他人行为，这很可贵，但也要留意关系中的潜在控制信号。这道题的关键是识别情感操控——用分手威胁来干涉你的社交，属于越界行为。学会设定边界，比如明确表达“我不接受威胁”，是保护自己的重要方式。建议今后遇到类似情况，先冷静判断对方言语是否带有胁迫或内疚操控，及时与信任的人讨论。你已经迈出了学习的第一步，继续提升觉察力，会更从容应对复杂人际情境。', '[{\"id\": 1, \"text\": \"网络欺凌\", \"is_correct\": true, \"description\": \"在网络平台上恶意传播和攻击\", \"is_selected\": false}, {\"id\": 2, \"text\": \"普通聊天\", \"is_correct\": false, \"description\": \"同学间的日常交流\", \"is_selected\": true}, {\"id\": 3, \"text\": \"开玩笑\", \"is_correct\": false, \"description\": \"只是开个小玩笑\", \"is_selected\": false}]', 1, '2025-10-10 19:09:10');
INSERT INTO `protection_drill_question_details` VALUES (12, 5, 54, '校园暴力识别', '这种威胁属于什么性质？', 2, '同学冲突', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你选择“同学冲突”说明你在积极思考人际关系的性质，这很棒！但这次的情况更接近情感操控，通过威胁分手来限制对方交友，本质是边界被侵犯。关键要学的是：健康的关系需要明确且相互尊重的个人边界。在现实中，若有人用“你要是和别人玩，我就离开你”这类话，记得冷静回应：“我理解你的感受，但我的交友权是我的边界”。建议你多关注情绪中的压力感，练习温和而坚定地表达底线。你已经在进步的路上了，继续加油！', '[{\"id\": 1, \"text\": \"校园暴力\", \"is_correct\": true, \"description\": \"使用暴力威胁的恶性行为\", \"is_selected\": false}, {\"id\": 2, \"text\": \"同学冲突\", \"is_correct\": false, \"description\": \"普通的同学矛盾\", \"is_selected\": true}, {\"id\": 3, \"text\": \"开玩笑\", \"is_correct\": false, \"description\": \"年龄差异的玩笑\", \"is_selected\": false}]', 2, '2025-10-10 19:09:15');
INSERT INTO `protection_drill_question_details` VALUES (13, 4, 53, '校园诈骗识别', '这种信息可能是什么？', 2, '真实通知', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你好呀，感谢你的认真参与。你选择了“真实通知”，但其实这是一条试图通过情感操控来影响你判断的信息。重要的是要认识到：任何以分手威胁、逼迫你切断社交关系的言行，都是不健康的。我们要学会设定清晰的个人边界——爱是尊重，不是控制。在现实中，当你感到被胁迫时，记得冷静思考，勇敢说“不”。建议你多关注关系中的平等与尊重，练习坚定而温和地表达自己的底线。你值得被尊重，也要勇敢守护自己。继续加油，你在进步！', '[{\"id\": 1, \"text\": \"校园诈骗\", \"is_correct\": true, \"description\": \"冒充官方进行的诈骗\", \"is_selected\": false}, {\"id\": 2, \"text\": \"真实通知\", \"is_correct\": false, \"description\": \"确实的奖学金通知\", \"is_selected\": true}, {\"id\": 3, \"text\": \"学校信息\", \"is_correct\": false, \"description\": \"学校发送的正式通知\", \"is_selected\": false}]', 3, '2025-10-10 19:09:19');
INSERT INTO `protection_drill_question_details` VALUES (14, 5, 53, '校园诈骗识别', '这种信息可能是什么？', 2, '真实通知', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你的选择反映出你在关心他人感受，这很可贵。但这次答案提醒我们：当有人用“分手”来威胁你断绝正常社交时，其实是情感操控的信号。关键要学到：爱不会绑架人，健康的关系尊重彼此边界。请记住，设定清晰的个人边界不是冷漠，而是自护的智慧。今后遇到类似情况，试着温和而坚定地表达：“我愿意和你沟通，但不能接受威胁。”建议你练习识别情绪勒索的常见话术，并提前想好应对方式。你已经迈出了学习的重要一步，继续加油！', '[{\"id\": 1, \"text\": \"校园诈骗\", \"is_correct\": true, \"description\": \"冒充官方进行的诈骗\", \"is_selected\": false}, {\"id\": 2, \"text\": \"真实通知\", \"is_correct\": false, \"description\": \"确实的奖学金通知\", \"is_selected\": true}, {\"id\": 3, \"text\": \"学校信息\", \"is_correct\": false, \"description\": \"学校发送的正式通知\", \"is_selected\": false}]', 3, '2025-10-10 19:09:21');
INSERT INTO `protection_drill_question_details` VALUES (15, 4, 49, '校园安全风险', '这种情况属于什么类型的校园风险？', 2, '正常社交', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '谢谢你认真完成这道题！你选择了“正常社交”，说明你重视关系中的和谐，这很可贵。但这种情况其实属于情感操控，核心风险是对方用“分手”来控制你的社交，这是需要警惕的。关键要学的是：健康的关系必须包含清晰的个人边界。在现实中，当伴侣以情绪或分离相威胁时，记得温和而坚定地表达自己的底线。建议你多关注关系中的“是否被尊重”而非“是否和睦”。下次遇到类似情境，试着问自己：“如果我不答应，我会被惩罚吗？”继续加油，你正在迈出自我保护的重要一步！', '[{\"id\": 1, \"text\": \"校园霸凌\", \"is_correct\": true, \"description\": \"恶意排挤和威胁他人的行为\", \"is_selected\": false}, {\"id\": 2, \"text\": \"正常社交\", \"is_correct\": false, \"description\": \"同学之间的普通交流\", \"is_selected\": true}, {\"id\": 3, \"text\": \"开玩笑\", \"is_correct\": false, \"description\": \"只是在开玩笑而已\", \"is_selected\": false}]', 4, '2025-10-10 19:09:24');
INSERT INTO `protection_drill_question_details` VALUES (16, 4, 50, '异常关注识别', '这种行为可能存在什么风险？', 2, '友好交流', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你的选择体现了善意和沟通的意愿，这很可贵。但面对情感操控行为，如以分手威胁来限制社交，友好交流可能被误解为让步。关键要先明确设定个人边界——这是自我保护的核心。学会识别操控信号，比如情绪勒索或关系绑架，并坚定表达“我可以关心你，但也需要尊重自己的社交自由”。建议你在类似情境中先问自己：“这个要求是否让我感到被控制？”然后练习温和而清晰地表达界限。继续加油，你正在建立更重要的自我觉察能力！', '[{\"id\": 1, \"text\": \"异常关注\", \"is_correct\": true, \"description\": \"可能的跟踪或不良企图\", \"is_selected\": false}, {\"id\": 2, \"text\": \"友好交流\", \"is_correct\": false, \"description\": \"想要结交朋友\", \"is_selected\": true}, {\"id\": 3, \"text\": \"路人询问\", \"is_correct\": false, \"description\": \"普通的路人询问\", \"is_selected\": false}]', 5, '2025-10-10 19:09:29');
INSERT INTO `protection_drill_question_details` VALUES (17, 5, 49, '校园安全风险', '这种情况属于什么类型的校园风险？', 2, '正常社交', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你选择“正常社交”说明你在用善意理解关系，这很可贵。但这次的情况其实是情感操控的信号——当对方用“分手”来威胁你断绝社交时，已属于越界行为。关键要记住：健康的关系不会以切断你的支持系统为代价。学会温和而坚定地设定边界，比如：“我重视我们的关系，但也需要和朋友保持联系。”这是保护自己的重要方式。建议今后多留意关系中是否有类似“威胁性要求”，及时识别并沟通，必要时寻求信任的人或专业人士支持。你值得被尊重，包括在亲密关系中。继续学习，你已经在进步的路上了！', '[{\"id\": 1, \"text\": \"校园霸凌\", \"is_correct\": true, \"description\": \"恶意排挤和威胁他人的行为\", \"is_selected\": false}, {\"id\": 2, \"text\": \"正常社交\", \"is_correct\": false, \"description\": \"同学之间的普通交流\", \"is_selected\": true}, {\"id\": 3, \"text\": \"开玩笑\", \"is_correct\": false, \"description\": \"只是在开玩笑而已\", \"is_selected\": false}]', 4, '2025-10-10 19:09:32');
INSERT INTO `protection_drill_question_details` VALUES (18, 4, 51, '不当邀请识别', '这种邀请存在什么潜在风险？', 1, '不当邀请', 1, '不当邀请', 1, 10, '你正确识别了这个风险信号！应该明确设定个人边界', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你做得非常棒！准确识别出这是不当邀请，说明你对情感操控的警觉性很高。关键是要记住：健康的关系不会用分手来威胁你服从。学会坚定表达“我有权决定自己的社交”，并观察对方是否尊重你的边界。今后遇到类似情况，可以提前想好回应方式，比如平静而明确地拒绝不合理要求。继续保持这份敏锐和自信，你的自我保护能力会越来越强！', '[{\"id\": 1, \"text\": \"不当邀请\", \"is_correct\": true, \"description\": \"可能存在安全隐患的邀请\", \"is_selected\": true}, {\"id\": 2, \"text\": \"友好邀请\", \"is_correct\": false, \"description\": \"同学间的正常邀请\", \"is_selected\": false}, {\"id\": 3, \"text\": \"特殊体验\", \"is_correct\": false, \"description\": \"想分享特别的地方\", \"is_selected\": false}]', 6, '2025-10-10 19:09:36');
INSERT INTO `protection_drill_question_details` VALUES (19, 5, 50, '异常关注识别', '这种行为可能存在什么风险？', 2, '友好交流', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '谢谢你认真完成这道题目！你选择“友好交流”体现了你的善意和包容，这很可贵。但面对情感操控类行为，比如以分手威胁来干涉你的社交，更重要的是及时**设定清晰的个人边界**。这是保护自己心理安全的关键一步。\n\n关键要认识到：健康的关系不会用威胁来控制对方。学会说“我可以理解你的感受，但我需要保持自己的社交空间”，既坚定又平和。\n\n建议你练习在类似情境中先识别情绪压力，再冷静表达底线。下次遇到类似情况，试着提前想好回应方式，保护自己不是冷漠，而是自爱。继续加油，你在进步的路上！', '[{\"id\": 1, \"text\": \"异常关注\", \"is_correct\": true, \"description\": \"可能的跟踪或不良企图\", \"is_selected\": false}, {\"id\": 2, \"text\": \"友好交流\", \"is_correct\": false, \"description\": \"想要结交朋友\", \"is_selected\": true}, {\"id\": 3, \"text\": \"路人询问\", \"is_correct\": false, \"description\": \"普通的路人询问\", \"is_selected\": false}]', 5, '2025-10-10 19:09:37');
INSERT INTO `protection_drill_question_details` VALUES (20, 5, 51, '不当邀请识别', '这种邀请存在什么潜在风险？', 1, '不当邀请', 1, '不当邀请', 1, 10, '你正确识别了这个风险信号！应该明确设定个人边界', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你做得很好，准确识别出这是不当邀请，展现了敏锐的风险觉察能力！关键学习点是：以分手相威胁来限制对方社交，属于情感操控的典型信号。在现实中，若有人用类似方式施压，请相信自己的感受，坚定表达“我有权决定自己的社交”。建议今后继续练习识别情绪勒索的言语模式，并提前准备回应话术，比如：“我不接受威胁，健康的关系需要尊重彼此自由。”你的边界值得被守护，继续保持这份清醒与勇气！', '[{\"id\": 1, \"text\": \"不当邀请\", \"is_correct\": true, \"description\": \"可能存在安全隐患的邀请\", \"is_selected\": true}, {\"id\": 2, \"text\": \"友好邀请\", \"is_correct\": false, \"description\": \"同学间的正常邀请\", \"is_selected\": false}, {\"id\": 3, \"text\": \"特殊体验\", \"is_correct\": false, \"description\": \"想分享特别的地方\", \"is_selected\": false}]', 6, '2025-10-10 19:09:45');
INSERT INTO `protection_drill_question_details` VALUES (21, 6, 52, '网络欺凌识别', '这种行为属于什么类型的问题？', 2, '普通聊天', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '亲爱的学员，感谢你的诚实作答。你选择“普通聊天”说明你可能倾向于善意解读他人行为，这很可贵，但也要警惕那些披着聊天外衣的情感操控。这次的题目其实是在提醒我们：当有人用“如果你不听我的，我们就分手”这类话来干涉你的社交，这就是情感操控的信号。关键学习点是学会识别隐性威胁，并勇敢设定边界。在现实中，你可以练习温和而坚定地表达：“我理解你在意我，但我的朋友也是我重要的部分。”建议你多关注关系中的情绪变化，当感到被胁迫时，先暂停回应，给自己思考空间。你值得被尊重，而不是被控制。继续加油，你正在建立更强大的自我保护力！', '[{\"id\": 1, \"text\": \"网络欺凌\", \"is_correct\": true, \"description\": \"在网络平台上恶意传播和攻击\", \"is_selected\": false}, {\"id\": 2, \"text\": \"普通聊天\", \"is_correct\": false, \"description\": \"同学间的日常交流\", \"is_selected\": true}, {\"id\": 3, \"text\": \"开玩笑\", \"is_correct\": false, \"description\": \"只是开个小玩笑\", \"is_selected\": false}]', 1, '2025-10-10 19:11:00');
INSERT INTO `protection_drill_question_details` VALUES (22, 6, 53, '校园诈骗识别', '这种信息可能是什么？', 1, '校园诈骗', 1, '校园诈骗', 1, 10, '你正确识别了这个风险信号！应该明确设定个人边界', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '太棒了！你准确识别出这是校园诈骗，展现了敏锐的风险意识。关键是要记住：任何试图通过情感操控（如威胁分手）来限制你社交的行为，都是不健康的警示信号。在现实中，请坚定维护个人边界，遇到类似情况及时与信任的人或学校相关部门沟通。你的判断力很强，接下来可以进一步学习如何识别隐蔽的情感操控话术，增强自我保护能力。继续保持这份警觉，你正在迈出安全成长的重要一步！', '[{\"id\": 1, \"text\": \"校园诈骗\", \"is_correct\": true, \"description\": \"冒充官方进行的诈骗\", \"is_selected\": true}, {\"id\": 2, \"text\": \"真实通知\", \"is_correct\": false, \"description\": \"确实的奖学金通知\", \"is_selected\": false}, {\"id\": 3, \"text\": \"学校信息\", \"is_correct\": false, \"description\": \"学校发送的正式通知\", \"is_selected\": false}]', 2, '2025-10-10 19:11:04');
INSERT INTO `protection_drill_question_details` VALUES (23, 6, 54, '校园暴力识别', '这种威胁属于什么性质？', 2, '同学冲突', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你选择“同学冲突”说明你在积极思考关系中的互动，这很好。但这次的情况更接近情感操控，核心是对方用“分手”来威胁你，试图控制你的社交自由。关键要学的是：健康的关系需要清晰的个人边界。当有人以情感为筹码要求你顺从时，正是需要温和而坚定表达“我有权选择朋友”的时候。建议你练习说：“我理解你的感受，但我也有自己的交友原则。”今后遇到类似情况，先觉察是否被胁迫，再冷静回应。你已经迈出了学习的重要一步，继续加油！', '[{\"id\": 1, \"text\": \"校园暴力\", \"is_correct\": true, \"description\": \"使用暴力威胁的恶性行为\", \"is_selected\": false}, {\"id\": 2, \"text\": \"同学冲突\", \"is_correct\": false, \"description\": \"普通的同学矛盾\", \"is_selected\": true}, {\"id\": 3, \"text\": \"开玩笑\", \"is_correct\": false, \"description\": \"年龄差异的玩笑\", \"is_selected\": false}]', 3, '2025-10-10 19:11:12');
INSERT INTO `protection_drill_question_details` VALUES (24, 6, 50, '异常关注识别', '这种行为可能存在什么风险？', 1, '异常关注', 1, '异常关注', 1, 10, '你正确识别了这个风险信号！应该明确设定个人边界', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你做得非常棒！准确识别出“异常关注”是保护自己的第一步。这道题提醒我们，当有人用威胁分手来干涉你的社交时，可能是在进行情感操控。关键是要学会坚定设立个人边界，比如明确表达“我有权保持自己的朋友圈”。在现实中，若对方持续施压，请及时向信任的人或专业人士求助。继续保持这份警觉，同时相信自己的感受，你已经走在建立健康关系的正确道路上了！', '[{\"id\": 1, \"text\": \"异常关注\", \"is_correct\": true, \"description\": \"可能的跟踪或不良企图\", \"is_selected\": true}, {\"id\": 2, \"text\": \"友好交流\", \"is_correct\": false, \"description\": \"想要结交朋友\", \"is_selected\": false}, {\"id\": 3, \"text\": \"路人询问\", \"is_correct\": false, \"description\": \"普通的路人询问\", \"is_selected\": false}]', 4, '2025-10-10 19:11:15');
INSERT INTO `protection_drill_question_details` VALUES (25, 6, 49, '校园安全风险', '这种情况属于什么类型的校园风险？', 1, '校园霸凌', 1, '校园霸凌', 1, 10, '你正确识别了这个风险信号！应该明确设定个人边界', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你做得很好！能准确识别出这是校园霸凌的一种表现，说明你对情感操控的风险有敏锐的觉察。关键要记住：健康的关系从不靠威胁维系。学会明确设立个人边界，比如清楚表达“我不接受被威胁”这样的底线。在现实中，若遇到类似情况，及时向信任的老师或家人求助，并记录事件经过。继续保持这份警觉，同时增强自信表达的能力，你会更从容地保护自己。相信自己的感受，你的安全永远最重要。', '[{\"id\": 1, \"text\": \"校园霸凌\", \"is_correct\": true, \"description\": \"恶意排挤和威胁他人的行为\", \"is_selected\": true}, {\"id\": 2, \"text\": \"正常社交\", \"is_correct\": false, \"description\": \"同学之间的普通交流\", \"is_selected\": false}, {\"id\": 3, \"text\": \"开玩笑\", \"is_correct\": false, \"description\": \"只是在开玩笑而已\", \"is_selected\": false}]', 5, '2025-10-10 19:11:20');
INSERT INTO `protection_drill_question_details` VALUES (26, 6, 51, '不当邀请识别', '这种邀请存在什么潜在风险？', 1, '不当邀请', 1, '不当邀请', 1, 10, '你正确识别了这个风险信号！应该明确设定个人边界', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你做得很好！能准确识别出这是不当邀请，说明你对情感操控的警觉性很高。关键要记住：健康的关系不会用分手来威胁你切断社交。学会坚定表达“我有权保持自己的朋友圈”是保护自我的重要一步。在现实中遇到类似情况时，可以冷静回应：“我不喜欢被逼做决定，这让我感到不舒服。” 继续相信你的直觉，它往往是最好的预警系统。接下来，试着练习几种温和但坚定的拒绝话术，让自我保护变得更自然流畅。你正在建立更安全、更尊重的关系边界，继续保持！', '[{\"id\": 1, \"text\": \"不当邀请\", \"is_correct\": true, \"description\": \"可能存在安全隐患的邀请\", \"is_selected\": true}, {\"id\": 2, \"text\": \"友好邀请\", \"is_correct\": false, \"description\": \"同学间的正常邀请\", \"is_selected\": false}, {\"id\": 3, \"text\": \"特殊体验\", \"is_correct\": false, \"description\": \"想分享特别的地方\", \"is_selected\": false}]', 6, '2025-10-10 19:11:26');
INSERT INTO `protection_drill_question_details` VALUES (27, 7, 38, '职场孤立识别', '这种行为构成什么问题？', 1, '职场孤立', 1, '职场孤立', 1, 10, '你正确识别了这个风险信号！应该明确设定个人边界', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '继续加油！每道题都是学习的机会。', '[{\"id\": 1, \"text\": \"职场孤立\", \"is_correct\": true, \"description\": \"故意排斥和孤立同事\", \"is_selected\": true}, {\"id\": 2, \"text\": \"团队优化\", \"is_correct\": false, \"description\": \"提高团队效率\", \"is_selected\": false}, {\"id\": 3, \"text\": \"信息安全\", \"is_correct\": false, \"description\": \"保护项目机密\", \"is_selected\": false}]', 1, '2025-10-10 19:12:18');
INSERT INTO `protection_drill_question_details` VALUES (28, 7, 37, '不公平待遇识别', '这种做法违反了什么原则？', 2, '能力差异', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '继续加油！每道题都是学习的机会。', '[{\"id\": 1, \"text\": \"同工同酬\", \"is_correct\": true, \"description\": \"相同工作应获得相同报酬\", \"is_selected\": false}, {\"id\": 2, \"text\": \"能力差异\", \"is_correct\": false, \"description\": \"基于能力的合理安排\", \"is_selected\": true}, {\"id\": 3, \"text\": \"经验考虑\", \"is_correct\": false, \"description\": \"根据工作经验分配\", \"is_selected\": false}]', 2, '2025-10-10 19:12:18');
