INSERT INTO `protection_drill_question_details` VALUES (35, 9, 3, '贬低打击识别', '这些话语的主要目的是什么？', 2, '实话实说', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你好，感谢你的认真练习！你选择了“实话实说”，说明你重视真诚沟通，这很可贵。但在这类情境中，对方的话语其实是情感操控的信号，真正需要的是“设定边界”。我们要学会识别以分手威胁来控制社交的行为，这不是坦诚，而是越界。关键是要保护自己的情绪安全，明确表达“我可以讨论我的朋友，但不能接受威胁”。建议你今后遇到类似话语时，先觉察是否感到被压迫，再冷静回应底线。你已经迈出了学习的重要一步，继续加油！', '[{\"id\": 1, \"text\": \"贬低自尊\", \"is_correct\": true, \"description\": \"通过贬低来控制对方\", \"is_selected\": false}, {\"id\": 2, \"text\": \"实话实说\", \"is_correct\": false, \"description\": \"客观评价对方条件\", \"is_selected\": true}, {\"id\": 3, \"text\": \"开玩笑\", \"is_correct\": false, \"description\": \"只是开玩笑而已\", \"is_selected\": false}]', 1, '2025-10-10 19:21:39');
INSERT INTO `protection_drill_question_details` VALUES (36, 8, 3, '贬低打击识别', '这些话语的主要目的是什么？', 2, '实话实说', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你选择“实话实说”说明你在努力理解对方的表达，这很可贵。但这句话其实是一种情感操控，目的是通过威胁分手来控制你的社交自由。真正的沟通不应伴随胁迫。关键要记住：健康的关系尊重彼此边界。当对方用“你要是见他，我们就分手”这类话时，正是需要你温和而坚定地设立边界的时候。建议你练习识别这类语言背后的控制意图，并提前准备好回应方式，比如：“我理解你的担心，但我也有权维护自己的朋友关系。”继续加油，你正在建立更强大的自我保护能力。', '[{\"id\": 1, \"text\": \"贬低自尊\", \"is_correct\": true, \"description\": \"通过贬低来控制对方\", \"is_selected\": false}, {\"id\": 2, \"text\": \"实话实说\", \"is_correct\": false, \"description\": \"客观评价对方条件\", \"is_selected\": true}, {\"id\": 3, \"text\": \"开玩笑\", \"is_correct\": false, \"description\": \"只是开玩笑而已\", \"is_selected\": false}]', 1, '2025-10-10 19:21:41');
INSERT INTO `protection_drill_question_details` VALUES (37, 9, 1, '情感操控识别', '这种行为属于什么类型的风险信号？', 1, '情感操控', 1, '情感操控', 1, 10, '你正确识别了这个风险信号！应该明确设定个人边界', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你做得非常棒！准确识别出“情感操控”这一风险信号，展现了敏锐的觉察力。关键学习点是：以分手相威胁来限制对方社交，是典型的情感操控手段。在现实中，当感到被胁迫或不安时，请坚定维护自己的人际自由和情绪边界。建议你继续信任自己的感受，遇到类似情况时，及时与信任的人沟通，必要时寻求专业支持。保持这份警觉，你正在建立更安全、健康的关系模式，继续加油！', '[{\"id\": 1, \"text\": \"情感操控\", \"is_correct\": true, \"description\": \"通过威胁分手来控制对方行为\", \"is_selected\": true}, {\"id\": 2, \"text\": \"正常要求\", \"is_correct\": false, \"description\": \"恋人之间的合理期望\", \"is_selected\": false}, {\"id\": 3, \"text\": \"沟通不当\", \"is_correct\": false, \"description\": \"只是表达方式有问题\", \"is_selected\": false}]', 2, '2025-10-10 19:21:42');
INSERT INTO `protection_drill_question_details` VALUES (38, 8, 1, '情感操控识别', '这种行为属于什么类型的风险信号？', 1, '情感操控', 1, '情感操控', 1, 10, '你正确识别了这个风险信号！应该明确设定个人边界', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '太棒了！你准确识别出这是情感操控，展现了敏锐的觉察能力。关键学习点是：以分手相威胁来限制对方社交，是典型的情感操控信号，往往伴随着边界侵犯。在现实中，当有人用“如果你去聚会，我们就分手”这类话语时，请相信自己的感受，坚定表达“我有权保持健康的社交”。建议你继续练习识别其他操控手段，如内疚施压或贬低，并提前想好应对方式，比如冷静回应或暂时离开对话。你正在建立重要的自我保护能力，继续保持这份清醒与勇气！', '[{\"id\": 1, \"text\": \"情感操控\", \"is_correct\": true, \"description\": \"通过威胁分手来控制对方行为\", \"is_selected\": true}, {\"id\": 2, \"text\": \"正常要求\", \"is_correct\": false, \"description\": \"恋人之间的合理期望\", \"is_selected\": false}, {\"id\": 3, \"text\": \"沟通不当\", \"is_correct\": false, \"description\": \"只是表达方式有问题\", \"is_selected\": false}]', 2, '2025-10-10 19:21:45');
INSERT INTO `protection_drill_question_details` VALUES (39, 9, 14, '职业干涉识别', '这种要求属于什么类型的控制？', 3, '关系优先', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你的选择显示出你在重视关系和谐方面有很强的觉察，这很可贵。但这次的情况属于情感操控，对方用“分手”来施压，本质是越界控制。关键学习点是：健康的关系必须建立在清晰的个人边界之上，而不是一味迁就。生活中，当有人以切断关系威胁你做某事时，要警惕这是操控行为。建议你练习温和而坚定地表达底线，比如：“我理解你的担心，但我需要有自己的社交空间。”继续加强边界意识训练，你会更自信地守护自我与关系的平衡，很棒，继续加油！', '[{\"id\": 1, \"text\": \"职业干涉\", \"is_correct\": true, \"description\": \"干涉对方的职业发展\", \"is_selected\": false}, {\"id\": 2, \"text\": \"关心体贴\", \"is_correct\": false, \"description\": \"想要照顾对方\", \"is_selected\": false}, {\"id\": 3, \"text\": \"关系优先\", \"is_correct\": false, \"description\": \"重视两人关系\", \"is_selected\": true}]', 3, '2025-10-10 19:21:47');
INSERT INTO `protection_drill_question_details` VALUES (40, 8, 14, '职业干涉识别', '这种要求属于什么类型的控制？', 3, '关系优先', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你选择“关系优先”说明你在意亲密关系的和谐，这份用心很可贵。但这次的情况其实是情感操控的信号——用分手威胁来干涉你的社交，这需要我们及时设定边界来保护自己。关键是要明白：健康的关系不会以失去自我为代价。学会说“我理解你在意，但我也有朋友需要维系”，是爱自己、守护心理安全的重要一步。建议今后遇到类似情况，先觉察自己的感受，再温和而坚定地表达界限。你值得被尊重，包括在人际关系的选择上。继续加油，你的觉察能力会越来越强！', '[{\"id\": 1, \"text\": \"职业干涉\", \"is_correct\": true, \"description\": \"干涉对方的职业发展\", \"is_selected\": false}, {\"id\": 2, \"text\": \"关心体贴\", \"is_correct\": false, \"description\": \"想要照顾对方\", \"is_selected\": false}, {\"id\": 3, \"text\": \"关系优先\", \"is_correct\": false, \"description\": \"重视两人关系\", \"is_selected\": true}]', 3, '2025-10-10 19:21:49');
INSERT INTO `protection_drill_question_details` VALUES (41, 9, 15, '家庭孤立识别', '这种要求的目的是什么？', 2, '独立生活', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你的选择显示出对自主生活的重视，这是很可贵的。不过这道题的关键在于识别情感操控——对方以“分手”威胁你断绝社交，本质是越界控制。我们要学会的不是逃离关系，而是设立清晰边界：“我珍惜我们的关系，但也需要和家人朋友保持联系。” 这样既尊重自己，也维护关系健康。建议练习用平和而坚定的方式表达界限，比如提前沟通、温和拒绝不合理要求。你已经迈出了觉察的第一步，继续加油！', '[{\"id\": 1, \"text\": \"家庭孤立\", \"is_correct\": true, \"description\": \"切断与家人的联系\", \"is_selected\": false}, {\"id\": 2, \"text\": \"独立生活\", \"is_correct\": false, \"description\": \"建立独立的家庭\", \"is_selected\": true}, {\"id\": 3, \"text\": \"关系保护\", \"is_correct\": false, \"description\": \"保护恋爱关系\", \"is_selected\": false}]', 4, '2025-10-10 19:21:51');
INSERT INTO `protection_drill_question_details` VALUES (42, 8, 15, '家庭孤立识别', '这种要求的目的是什么？', 2, '独立生活', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你选择“独立生活”说明你有追求自主的意识，这很可贵。这道题目的核心是识别情感操控——当对方以分手威胁来干涉你的社交时，重点不是逃离关系，而是建立清晰的个人边界。学会温和而坚定地表达“我可以和家人保持联系，这是我的需要”，既能保护自己，又避免被控制。建议练习边界沟通话术，比如“我理解你的感受，但我不接受威胁”。你的觉察力正在成长，继续加油！', '[{\"id\": 1, \"text\": \"家庭孤立\", \"is_correct\": true, \"description\": \"切断与家人的联系\", \"is_selected\": false}, {\"id\": 2, \"text\": \"独立生活\", \"is_correct\": false, \"description\": \"建立独立的家庭\", \"is_selected\": true}, {\"id\": 3, \"text\": \"关系保护\", \"is_correct\": false, \"description\": \"保护恋爱关系\", \"is_selected\": false}]', 4, '2025-10-10 19:21:54');
INSERT INTO `protection_drill_question_details` VALUES (43, 9, 2, '孤立策略识别', '这种做法最可能属于什么操控手段？', 2, '关心表现', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你的选择显示出你倾向于从善意角度理解他人，这很可贵。但这次情况其实是一种情感操控——用“分手”威胁来切断对方社交，本质是控制而非关心。关键要学的是：健康的关系尊重彼此社交自由，真正的情感安全来自清晰的个人边界。今后遇到类似“你要是还和TA来往，我们就分手”的说法，请立刻警觉，这并非爱的表现，而是操控的信号。建议你练习坚定表达：“我理解你的感受，但我需要保持自己的朋友圈。”继续提升识别能力，你已经在进步的路上了！', '[{\"id\": 1, \"text\": \"孤立策略\", \"is_correct\": true, \"description\": \"试图切断对方的社交联系\", \"is_selected\": false}, {\"id\": 2, \"text\": \"关心表现\", \"is_correct\": false, \"description\": \"出于关心的善意建议\", \"is_selected\": true}, {\"id\": 3, \"text\": \"嫉妒心理\", \"is_correct\": false, \"description\": \"普通的嫉妒情绪\", \"is_selected\": false}]', 5, '2025-10-10 19:21:56');
INSERT INTO `protection_drill_question_details` VALUES (44, 9, 16, '完美主义操控识别', '这种要求存在什么问题？', 1, '完美主义操控', 1, '完美主义操控', 1, 10, '你正确识别了这个风险信号！应该明确设定个人边界', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '太棒了！你准确识别出“完美主义操控”这一情感操控形式，展现了敏锐的觉察力。关键要记住：任何人以分手威胁来干预你的社交，都是越界行为。请坚定维护自己的人际自由，设定清晰边界。建议日常中持续练习说“我需要保持和朋友的联系，这对我很重要”，既表达立场又保护关系。继续保持这份警觉，你正在建立强大的自我保护能力，相信自己值得被尊重与善待。', '[{\"id\": 1, \"text\": \"完美主义操控\", \"is_correct\": true, \"description\": \"设置不现实的完美标准\", \"is_selected\": true}, {\"id\": 2, \"text\": \"高标准要求\", \"is_correct\": false, \"description\": \"对关系的高标准\", \"is_selected\": false}, {\"id\": 3, \"text\": \"追求进步\", \"is_correct\": false, \"description\": \"希望对方更好\", \"is_selected\": false}]', 6, '2025-10-10 19:22:00');
INSERT INTO `protection_drill_question_details` VALUES (45, 8, 2, '孤立策略识别', '这种做法最可能属于什么操控手段？', 2, '关心表现', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你的选择显示出你在关注关系中的善意动机，这很可贵。但这次混淆了“关心”与“操控”的界限。关键要记住：任何以分手威胁来限制你社交的行为，都是情感操控的信号。学会识别这种孤立策略，是保护自己的第一步。在现实中，当有人要求你断绝与朋友或家人的联系时，要警惕并坚定表达：“我理解你的感受，但我需要保留我的支持系统。” 建议你多练习区分“健康的关心”和“控制性的要求”，比如写下类似情境并标注边界点。你已经迈出了学习的重要一步，继续加油，你会越来越有力量守护自己。', '[{\"id\": 1, \"text\": \"孤立策略\", \"is_correct\": true, \"description\": \"试图切断对方的社交联系\", \"is_selected\": false}, {\"id\": 2, \"text\": \"关心表现\", \"is_correct\": false, \"description\": \"出于关心的善意建议\", \"is_selected\": true}, {\"id\": 3, \"text\": \"嫉妒心理\", \"is_correct\": false, \"description\": \"普通的嫉妒情绪\", \"is_selected\": false}]', 5, '2025-10-10 19:22:01');
INSERT INTO `protection_drill_question_details` VALUES (46, 9, 9, '情绪操控识别', '这种表达方式的本质是什么？', 1, '情绪操控', 1, '情绪操控', 1, 10, '你正确识别了这个风险信号！应该明确设定个人边界', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你做得非常棒！准确识别出“情绪操控”是保护自己的关键第一步。这道题提醒我们，当有人用“分手”威胁来干涉你的社交时，本质是通过制造恐惧控制你。请记住：健康的关系尊重个人边界。现实中，若遇到类似情况，试着冷静表达：“我理解你的担心，但我需要和朋友保持联系。”同时观察对方是否尊重你的回应。继续保持这种敏锐觉察，你已经走在建立安全关系的正确道路上了，为你点赞！', '[{\"id\": 1, \"text\": \"情绪操控\", \"is_correct\": true, \"description\": \"利用情绪来控制对方行为\", \"is_selected\": true}, {\"id\": 2, \"text\": \"情感表达\", \"is_correct\": false, \"description\": \"真实的情感表达\", \"is_selected\": false}, {\"id\": 3, \"text\": \"沟通需求\", \"is_correct\": false, \"description\": \"表达自己的需求\", \"is_selected\": false}]', 7, '2025-10-10 19:22:04');
INSERT INTO `protection_drill_question_details` VALUES (47, 8, 16, '完美主义操控识别', '这种要求存在什么问题？', 1, '完美主义操控', 1, '完美主义操控', 1, 10, '你正确识别了这个风险信号！应该明确设定个人边界', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你做得很好！准确识别出“完美主义操控”是建立健康关系的重要一步。这道题的关键在于认识到：用分手威胁来控制对方社交，是一种情感操控的信号。记住，每个人都应拥有合理的个人边界和社交自由。在现实中，若对方以“不够好”为由限制你与朋友来往，请温和而坚定地表达：“我理解你的担忧，但我的友谊对我很重要。”继续保持这种觉察能力，同时建议你练习设定边界的具体话术，增强应对信心。你正在迈出保护自己情感安全的有力一步，值得肯定！', '[{\"id\": 1, \"text\": \"完美主义操控\", \"is_correct\": true, \"description\": \"设置不现实的完美标准\", \"is_selected\": true}, {\"id\": 2, \"text\": \"高标准要求\", \"is_correct\": false, \"description\": \"对关系的高标准\", \"is_selected\": false}, {\"id\": 3, \"text\": \"追求进步\", \"is_correct\": false, \"description\": \"希望对方更好\", \"is_selected\": false}]', 6, '2025-10-10 19:22:06');
INSERT INTO `protection_drill_question_details` VALUES (48, 9, 5, '情感勒索识别', '这种表达方式属于什么类型的问题？', 1, '情感勒索', 1, '情感勒索', 1, 10, '你正确识别了这个风险信号！应该明确设定个人边界', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你做得很好！准确识别出情感勒索是保护自己的重要第一步。这道题的关键是学会辨识“以威胁维系控制”的操控模式，比如用分手胁迫对方切断社交。记住，健康的关系尊重个人边界。在现实中，若对方以情绪或关系为筹码施压，请冷静回应：“我理解你的担心，但我需要被尊重。”建议你继续练习设定清晰边界，比如提前明确哪些行为不可接受，并坚定表达。保持觉察，你正在建立更安全的人际防护力。', '[{\"id\": 1, \"text\": \"情感勒索\", \"is_correct\": true, \"description\": \"利用内疚感来控制对方\", \"is_selected\": true}, {\"id\": 2, \"text\": \"合理担心\", \"is_correct\": false, \"description\": \"对关系的正常关切\", \"is_selected\": false}, {\"id\": 3, \"text\": \"表达需求\", \"is_correct\": false, \"description\": \"希望得到更多陪伴\", \"is_selected\": false}]', 8, '2025-10-10 19:22:08');
INSERT INTO `protection_drill_question_details` VALUES (49, 8, 9, '情绪操控识别', '这种表达方式的本质是什么？', 1, '情绪操控', 1, '情绪操控', 1, 10, '你正确识别了这个风险信号！应该明确设定个人边界', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '太棒了！你准确识别出这是情绪操控，展现了敏锐的觉察能力。关键学习点是：以分手相威胁来限制对方社交，是典型的情感操控手段，往往掩盖真实控制意图。在现实中，若伴侣用“你要是去聚会，我们就没未来”之类的话施压，要冷静识别这并非爱的表现，而是边界侵犯。建议你继续强化“情绪红灯”意识——每当感到被胁迫或内疚驱动时，暂停回应，回归自我感受。下一步可练习坚定而温和地表达边界，比如：“我理解你的担心，但我不接受威胁式的沟通。”继续保持这份清醒，你正走在更安全、更健康的关系道路上。', '[{\"id\": 1, \"text\": \"情绪操控\", \"is_correct\": true, \"description\": \"利用情绪来控制对方行为\", \"is_selected\": true}, {\"id\": 2, \"text\": \"情感表达\", \"is_correct\": false, \"description\": \"真实的情感表达\", \"is_selected\": false}, {\"id\": 3, \"text\": \"沟通需求\", \"is_correct\": false, \"description\": \"表达自己的需求\", \"is_selected\": false}]', 7, '2025-10-10 19:22:13');
INSERT INTO `protection_drill_question_details` VALUES (50, 8, 5, '情感勒索识别', '这种表达方式属于什么类型的问题？', 1, '情感勒索', 1, '情感勒索', 1, 10, '你正确识别了这个风险信号！应该明确设定个人边界', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你做得很好！准确识别出情感勒索是保护自己的重要第一步。这道题提醒我们，当有人用“再这样我就分手”来干涉你的社交时，本质是通过制造内疚或恐惧来控制你。请记住：健康的关系尊重个人边界。在现实中，若遇到类似话语，可以冷静表达：“我理解你的担忧，但我需要保持自己的朋友和空间。”建议你继续练习识别其他操控信号，比如愧疚施压或贬低。你已经走在建立心理防线的正确道路上，继续保持觉察，你会更坚定地守护自己的情感安全。', '[{\"id\": 1, \"text\": \"情感勒索\", \"is_correct\": true, \"description\": \"利用内疚感来控制对方\", \"is_selected\": true}, {\"id\": 2, \"text\": \"合理担心\", \"is_correct\": false, \"description\": \"对关系的正常关切\", \"is_selected\": false}, {\"id\": 3, \"text\": \"表达需求\", \"is_correct\": false, \"description\": \"希望得到更多陪伴\", \"is_selected\": false}]', 8, '2025-10-10 19:22:18');
