INSERT INTO `protection_drill_question_details` VALUES (64, 11, 5, '情感勒索识别', '这种表达方式属于什么类型的问题？', 1, '情感勒索', 1, '情感勒索', 1, 10, '你正确识别了这个风险信号！应该明确设定个人边界', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '正在生成个性化反馈...', '[{\"id\": 1, \"text\": \"情感勒索\", \"is_correct\": true, \"description\": \"利用内疚感来控制对方\", \"is_selected\": true}, {\"id\": 2, \"text\": \"合理担心\", \"is_correct\": false, \"description\": \"对关系的正常关切\", \"is_selected\": false}, {\"id\": 3, \"text\": \"表达需求\", \"is_correct\": false, \"description\": \"希望得到更多陪伴\", \"is_selected\": false}]', 6, '2025-10-10 19:28:08');
INSERT INTO `protection_drill_question_details` VALUES (65, 11, 1, '情感操控识别', '这种行为属于什么类型的风险信号？', 1, '情感操控', 1, '情感操控', 1, 10, '你正确识别了这个风险信号！应该明确设定个人边界', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '正在生成个性化反馈...', '[{\"id\": 1, \"text\": \"情感操控\", \"is_correct\": true, \"description\": \"通过威胁分手来控制对方行为\", \"is_selected\": true}, {\"id\": 2, \"text\": \"正常要求\", \"is_correct\": false, \"description\": \"恋人之间的合理期望\", \"is_selected\": false}, {\"id\": 3, \"text\": \"沟通不当\", \"is_correct\": false, \"description\": \"只是表达方式有问题\", \"is_selected\": false}]', 7, '2025-10-10 19:28:08');
INSERT INTO `protection_drill_question_details` VALUES (66, 11, 14, '职业干涉识别', '这种要求属于什么类型的控制？', 1, '职业干涉', 1, '职业干涉', 1, 10, '你正确识别了这个风险信号！应该明确设定个人边界', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '正在生成个性化反馈...', '[{\"id\": 1, \"text\": \"职业干涉\", \"is_correct\": true, \"description\": \"干涉对方的职业发展\", \"is_selected\": true}, {\"id\": 2, \"text\": \"关心体贴\", \"is_correct\": false, \"description\": \"想要照顾对方\", \"is_selected\": false}, {\"id\": 3, \"text\": \"关系优先\", \"is_correct\": false, \"description\": \"重视两人关系\", \"is_selected\": false}]', 8, '2025-10-10 19:28:08');
INSERT INTO `protection_drill_question_details` VALUES (67, 12, 30, '网络借贷风险', '这种借贷存在什么风险？', 3, '优惠贷款', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你选择“优惠贷款”说明你在关注表面的诱惑，这很常见。但本题的关键在于识别情感操控——用分手威胁来施压，是典型的越界行为。学习重点是要学会设定清晰的个人边界，不因情绪压力妥协财务安全。实际中，当对方以感情要挟涉及金钱时，要冷静说“不”，并重新评估关系健康度。建议你多练习识别“情感绑架”的信号，比如内疚诱导、威胁冷暴力等。你的警觉力正在成长，继续加油！下次遇到类似情境，先停一停，问问自己：“这个决定是我真心愿意，还是被迫顺从？”', '[{\"id\": 1, \"text\": \"高利贷陷阱\", \"is_correct\": true, \"description\": \"隐藏高额利息和费用\", \"is_selected\": false}, {\"id\": 2, \"text\": \"便民服务\", \"is_correct\": false, \"description\": \"便民的金融服务\", \"is_selected\": false}, {\"id\": 3, \"text\": \"优惠贷款\", \"is_correct\": false, \"description\": \"优惠的贷款产品\", \"is_selected\": true}]', 1, '2025-10-10 19:30:21');
INSERT INTO `protection_drill_question_details` VALUES (68, 12, 29, '虚假慈善识别', '这种捐款方式存在什么问题？', 3, '紧急求助', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你选择“紧急求助”说明你意识到了情境中的危险，这很敏锐！但这次的正确应对是“设定边界”——关键在于提前明确自己的底线，比如不因情感压力而勉强捐款。学习要点是识别情感操控，尤其是以关系威胁施压的行为。实际中，当对方用“不捐就分手”之类的话时，要冷静回应：“我愿意帮助，但不能接受威胁。”建议你多练习坚定而温和地表达界限，保护自己不被情绪裹挟。你已经迈出了重要一步，继续加油！', '[{\"id\": 1, \"text\": \"虚假慈善\", \"is_correct\": true, \"description\": \"以慈善名义进行诈骗\", \"is_selected\": false}, {\"id\": 2, \"text\": \"真实救助\", \"is_correct\": false, \"description\": \"真实的慈善救助\", \"is_selected\": false}, {\"id\": 3, \"text\": \"紧急求助\", \"is_correct\": false, \"description\": \"紧急的医疗求助\", \"is_selected\": true}]', 2, '2025-10-10 19:30:21');
INSERT INTO `protection_drill_question_details` VALUES (69, 12, 28, '网络赌博诱惑', '这种邀请存在什么风险？', 3, '娱乐活动', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你选择“娱乐活动”说明你可能更倾向于善意理解他人意图，这很可贵。但这次邀请背后隐藏着情感操控的风险，用分手来施压是不健康的信号。关键要记住：真正的关系尊重个人边界。学会说“我需要时间考虑”或“这个我不 comfortable”，是保护自己的重要方式。建议今后遇到类似情况，先冷静判断对方是否在施加压力，再决定回应。你已经迈出了学习的重要一步，继续加油！', '[{\"id\": 1, \"text\": \"赌博诈骗\", \"is_correct\": true, \"description\": \"网络赌博和诈骗陷阱\", \"is_selected\": false}, {\"id\": 2, \"text\": \"投资机会\", \"is_correct\": false, \"description\": \"真实的投资机会\", \"is_selected\": false}, {\"id\": 3, \"text\": \"娱乐活动\", \"is_correct\": false, \"description\": \"正常的娱乐活动\", \"is_selected\": true}]', 3, '2025-10-10 19:30:21');
INSERT INTO `protection_drill_question_details` VALUES (70, 12, 27, '网络兼职陷阱', '这种兼职存在什么风险？', 3, '高薪工作', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你选择“高薪工作”说明你在关注潜在的利益诱惑，这是觉察风险的第一步，值得肯定。这道题的核心在于识别情感操控——对方用“分手”来逼迫你服从，是一种典型的边界侵犯。关键学习点是：无论关系多亲密，都要坚守个人边界，健康的关系不会以切断社交为代价。生活中，当有人用情绪或关系威胁你做 uncomfortable 的事，请记得温柔而坚定地说“不”。建议你多练习表达需求和拒绝的技巧，比如角色模拟，增强自信。你已经迈出了学习的重要一步，继续加油！', '[{\"id\": 1, \"text\": \"兼职诈骗\", \"is_correct\": true, \"description\": \"以兼职为名收取费用\", \"is_selected\": false}, {\"id\": 2, \"text\": \"真实兼职\", \"is_correct\": false, \"description\": \"真实的兼职机会\", \"is_selected\": false}, {\"id\": 3, \"text\": \"高薪工作\", \"is_correct\": false, \"description\": \"高收入的工作机会\", \"is_selected\": true}]', 4, '2025-10-10 19:30:21');
INSERT INTO `protection_drill_question_details` VALUES (71, 12, 26, '个人信息泄露', '这种要求存在什么风险？', 3, '身份确认', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你选择“身份确认”说明你在关注关系中的安全感，这很自然。但这次的正确答案是“设定边界”，因为对方用分手来施压，属于情感操控的信号。关键是要学会温和而坚定地表达底线，比如：“我理解你的担心，但不能接受用分手来要求我。” 真正健康的关系建立在尊重与信任上，而不是控制。建议你练习识别类似的情感勒索话术，并提前想好回应方式。你已经迈出了重要一步，继续提升觉察力，你会更从容地保护自己又不失温柔。', '[{\"id\": 1, \"text\": \"信息盗取\", \"is_correct\": true, \"description\": \"收集个人敏感信息\", \"is_selected\": false}, {\"id\": 2, \"text\": \"中奖验证\", \"is_correct\": false, \"description\": \"中奖需要的正常验证\", \"is_selected\": false}, {\"id\": 3, \"text\": \"身份确认\", \"is_correct\": false, \"description\": \"确认中奖者身份\", \"is_selected\": true}]', 5, '2025-10-10 19:30:21');
INSERT INTO `protection_drill_question_details` VALUES (72, 12, 25, '恶意软件风险', '这种下载存在什么风险？', 3, '试用版本', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你选择“试用版本”说明你在尝试寻找折中方式，这反映出你的善意与包容。但这次答案提醒我们：面对以分手相威胁要求下载监控软件的行为，关键不是妥协，而是坚定设定边界。这是典型的情感操控，牺牲自我安全换取关系稳定并不可持续。请记住：健康的关系建立在尊重与信任上，而非控制。建议你练习温和而坚定地表达底线，比如：“我理解你的不安，但我不能接受被监视。”今后遇到类似情境，优先保护自己的心理与数字安全，必要时寻求专业支持。你值得被尊重，而不是被威胁。', '[{\"id\": 1, \"text\": \"恶意软件\", \"is_correct\": true, \"description\": \"可能包含病毒或木马\", \"is_selected\": false}, {\"id\": 2, \"text\": \"正版软件\", \"is_correct\": false, \"description\": \"免费提供的正版软件\", \"is_selected\": false}, {\"id\": 3, \"text\": \"试用版本\", \"is_correct\": false, \"description\": \"软件的试用版本\", \"is_selected\": true}]', 6, '2025-10-10 19:30:21');
INSERT INTO `protection_drill_question_details` VALUES (73, 12, 20, '虚假身份识别', '这种情况需要注意什么风险？', 3, '行业规则', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你的选择显示出你对关系中的规则有一定关注，这很可贵。不过这次正确答案是“设定边界”，因为面对以分手威胁来控制社交的行为，核心是守住自己的情感底线。关键要识别这是情感操控的信号，学会坚定表达“我可以和谁交往，由我自己决定”。生活中遇到类似情况，记得先稳住自己，不被恐惧驱动，必要时寻求信任的人支持。建议你多练习说“我需要空间做决定”这类句子，增强自我保护力。你已经迈出了学习的重要一步，继续加油！', '[{\"id\": 1, \"text\": \"虚假身份\", \"is_correct\": true, \"description\": \"冒充职业身份进行诈骗\", \"is_selected\": false}, {\"id\": 2, \"text\": \"真实机会\", \"is_correct\": false, \"description\": \"确实的兼职机会\", \"is_selected\": false}, {\"id\": 3, \"text\": \"行业规则\", \"is_correct\": false, \"description\": \"模特行业的正常流程\", \"is_selected\": true}]', 7, '2025-10-10 19:30:21');
INSERT INTO `protection_drill_question_details` VALUES (74, 12, 19, '投资诈骗识别', '这种投资邀请最可能是什么？', 3, '内幕消息', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你选择“内幕消息”说明你在警惕投资风险，这很好！但本题核心在于识别情感操控——对方以分手相威胁，试图控制你的社交边界。关键是要学会设定清晰的个人边界，不因情绪压力妥协。生活中，当有人用情感要挟你做不愿做的事，记得温和而坚定地表达底线：“我理解你的感受，但我需要按自己的节奏来。”建议你多关注关系中的情绪信号，练习说“不”的技巧。你已经迈出了学习的重要一步，继续加油，自我保护能力会越来越强！', '[{\"id\": 1, \"text\": \"投资诈骗\", \"is_correct\": true, \"description\": \"以高收益诱导投资的骗局\", \"is_selected\": false}, {\"id\": 2, \"text\": \"投资机会\", \"is_correct\": false, \"description\": \"真实的投资项目\", \"is_selected\": false}, {\"id\": 3, \"text\": \"内幕消息\", \"is_correct\": false, \"description\": \"可靠的内部信息\", \"is_selected\": true}]', 8, '2025-10-10 19:30:21');
INSERT INTO `protection_drill_question_details` VALUES (75, 13, 30, '网络借贷风险', '这种借贷存在什么风险？', 3, '优惠贷款', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你选择“优惠贷款”说明你在关注表面诱因，这很好，但关键是要看到背后的情感操控风险。本题核心是学会设定边界——当对方以分手威胁来要求你借贷，本质是利用情感控制你。请记住：健康的关系不会让你在不安中做决定。今后遇到类似情况，先问自己：“如果我说不，对方能否尊重我？”建议你练习坚定而温和地表达底线，比如“这件事我需要时间考虑，不能勉强”。你已经迈出了学习的重要一步，继续加油，你会越来越有力量保护自己。', '[{\"id\": 1, \"text\": \"高利贷陷阱\", \"is_correct\": true, \"description\": \"隐藏高额利息和费用\", \"is_selected\": false}, {\"id\": 2, \"text\": \"便民服务\", \"is_correct\": false, \"description\": \"便民的金融服务\", \"is_selected\": false}, {\"id\": 3, \"text\": \"优惠贷款\", \"is_correct\": false, \"description\": \"优惠的贷款产品\", \"is_selected\": true}]', 1, '2025-10-10 19:30:21');
INSERT INTO `protection_drill_question_details` VALUES (76, 13, 29, '虚假慈善识别', '这种捐款方式存在什么问题？', 3, '紧急求助', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', 'AI服务暂时不可用，建议人工评估。', '[{\"id\": 1, \"text\": \"虚假慈善\", \"is_correct\": true, \"description\": \"以慈善名义进行诈骗\", \"is_selected\": false}, {\"id\": 2, \"text\": \"真实救助\", \"is_correct\": false, \"description\": \"真实的慈善救助\", \"is_selected\": false}, {\"id\": 3, \"text\": \"紧急求助\", \"is_correct\": false, \"description\": \"紧急的医疗求助\", \"is_selected\": true}]', 2, '2025-10-10 19:30:21');
INSERT INTO `protection_drill_question_details` VALUES (77, 13, 28, '网络赌博诱惑', '这种邀请存在什么风险？', 3, '娱乐活动', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你选择“娱乐活动”说明你在考虑情境的表面性质，这很正常。但关键在于识别背后的操控风险——用感情威胁来影响你的决定是危险信号。学习要点是：要敏锐觉察情感操控，及时设定清晰边界。在现实中，若有人以分手相逼要求你参与赌博或其他活动，请记住这并非爱的表现，而是控制。建议你练习坚定表达立场，比如：“我关心这段关系，但我的底线不会动摇。”继续加强风险预判训练，你会越来越有力量保护自己。相信自己，你正在进步！', '[{\"id\": 1, \"text\": \"赌博诈骗\", \"is_correct\": true, \"description\": \"网络赌博和诈骗陷阱\", \"is_selected\": false}, {\"id\": 2, \"text\": \"投资机会\", \"is_correct\": false, \"description\": \"真实的投资机会\", \"is_selected\": false}, {\"id\": 3, \"text\": \"娱乐活动\", \"is_correct\": false, \"description\": \"正常的娱乐活动\", \"is_selected\": true}]', 3, '2025-10-10 19:30:21');
INSERT INTO `protection_drill_question_details` VALUES (78, 13, 27, '网络兼职陷阱', '这种兼职存在什么风险？', 3, '高薪工作', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你选择“高薪工作”说明你关注到了外在诱惑，这很敏锐！但本题的关键在于识别情感操控的风险。真正重要的是学会设定个人边界——这是保护自己的核心技能。要明白，任何关系中都不应以分手相威胁来控制你的社交或决定。今后遇到类似情境，记得先问自己：“这个要求是否尊重我的感受和自主权？”建议你练习清晰表达底线，比如温和而坚定地说“我需要保持自己的朋友圈”。继续加油，你已经在成长的路上了！', '[{\"id\": 1, \"text\": \"兼职诈骗\", \"is_correct\": true, \"description\": \"以兼职为名收取费用\", \"is_selected\": false}, {\"id\": 2, \"text\": \"真实兼职\", \"is_correct\": false, \"description\": \"真实的兼职机会\", \"is_selected\": false}, {\"id\": 3, \"text\": \"高薪工作\", \"is_correct\": false, \"description\": \"高收入的工作机会\", \"is_selected\": true}]', 4, '2025-10-10 19:30:21');
INSERT INTO `protection_drill_question_details` VALUES (79, 13, 26, '个人信息泄露', '这种要求存在什么风险？', 3, '身份确认', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你选择“身份确认”说明你在关注关系中的安全感，这很宝贵。但这次的正确答案是“设定边界”，因为对方用分手来施压，是一种情感操控。我们要学会温和而坚定地表达底线，比如：“我理解你的担心，但不能接受威胁。”关键是要识别操控信号，保护自己的情绪空间。建议你练习说“不”的技巧，比如用“我感觉……当你说……我希望……”这样的句式。你已经在进步的路上，继续加油！每一次觉察都是自我保护能力的提升。', '[{\"id\": 1, \"text\": \"信息盗取\", \"is_correct\": true, \"description\": \"收集个人敏感信息\", \"is_selected\": false}, {\"id\": 2, \"text\": \"中奖验证\", \"is_correct\": false, \"description\": \"中奖需要的正常验证\", \"is_selected\": false}, {\"id\": 3, \"text\": \"身份确认\", \"is_correct\": false, \"description\": \"确认中奖者身份\", \"is_selected\": true}]', 5, '2025-10-10 19:30:21');
INSERT INTO `protection_drill_question_details` VALUES (80, 13, 25, '恶意软件风险', '这种下载存在什么风险？', 3, '试用版本', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你选择“试用版本”说明你在尝试寻找折中方式，这份灵活思考值得肯定。不过这道题的核心是识别情感操控——对方以分手相威胁，要求你切断社交联系，这是在挑战你的个人边界。关键学习点是：健康的关系尊重彼此的独立空间。现实中，当感到被胁迫时，请温和而坚定地表达底线：“我理解你的担心，但我的朋友对我来说很重要，我们可以一起找到安心的方式。”建议你多关注情绪直觉，若某要求让你不适，先暂停回应，给自己思考时间。你值得被尊重，而不是被控制。继续加油，你正在建立更强大的自我保护力！', '[{\"id\": 1, \"text\": \"恶意软件\", \"is_correct\": true, \"description\": \"可能包含病毒或木马\", \"is_selected\": false}, {\"id\": 2, \"text\": \"正版软件\", \"is_correct\": false, \"description\": \"免费提供的正版软件\", \"is_selected\": false}, {\"id\": 3, \"text\": \"试用版本\", \"is_correct\": false, \"description\": \"软件的试用版本\", \"is_selected\": true}]', 6, '2025-10-10 19:30:21');
INSERT INTO `protection_drill_question_details` VALUES (81, 13, 20, '虚假身份识别', '这种情况需要注意什么风险？', 3, '行业规则', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你选择“行业规则”说明你在尝试从规范角度思考问题，这很可贵。但本题核心是识别情感操控风险，正确答案“设定边界”提醒我们：面对以分手相威胁来干涉社交的行为，需坚定自我界限。关键是要意识到，健康的关系尊重彼此社交自由。生活中，若对方用情绪施压，请温和而坚定地表达“我可以理解你的担心，但不能接受威胁”。建议你多关注情感操控的早期信号，练习非暴力沟通方式，增强自我保护力。你已经迈出了学习的重要一步，继续加油！', '[{\"id\": 1, \"text\": \"虚假身份\", \"is_correct\": true, \"description\": \"冒充职业身份进行诈骗\", \"is_selected\": false}, {\"id\": 2, \"text\": \"真实机会\", \"is_correct\": false, \"description\": \"确实的兼职机会\", \"is_selected\": false}, {\"id\": 3, \"text\": \"行业规则\", \"is_correct\": false, \"description\": \"模特行业的正常流程\", \"is_selected\": true}]', 7, '2025-10-10 19:30:21');
INSERT INTO `protection_drill_question_details` VALUES (82, 13, 19, '投资诈骗识别', '这种投资邀请最可能是什么？', 3, '内幕消息', 1, '设定边界', 0, 3, '应该明确设定个人边界，不被情感威胁所绑架', '这是典型的情感操控行为，通过威胁分手来控制对方的社交关系。', '你的选择显示出你在积极思考潜在风险，这很棒！这道题的关键在于识别情感操控的信号。虽然“内幕消息”可能让人警觉，但核心问题是对方用分手来施压，这是在挑战你的人际边界。我们要学会坚定表达自己的原则，比如：“我理解你的想法，但我的决定不会因此改变。”真正健康的关系尊重彼此的选择。建议你多练习说“不”的技巧，增强自我价值感。你已经迈出了重要一步，继续加油，我会一直支持你提升安全防护能力！', '[{\"id\": 1, \"text\": \"投资诈骗\", \"is_correct\": true, \"description\": \"以高收益诱导投资的骗局\", \"is_selected\": false}, {\"id\": 2, \"text\": \"投资机会\", \"is_correct\": false, \"description\": \"真实的投资项目\", \"is_selected\": false}, {\"id\": 3, \"text\": \"内幕消息\", \"is_correct\": false, \"description\": \"可靠的内部信息\", \"is_selected\": true}]', 8, '2025-10-10 19:30:21');
