INSERT INTO `protection_drill_question_details` VALUES (163, 29, 21, '钓鱼链接识别', '对于这种链接应该如何处理？', 1, '谨慎对待', 1, '谨慎对待', 1, 10, '可能是钓鱼链接或恶意网站', '恶意链接可能盗取个人信息或植入病毒，需要谨慎对待。', '继续加油！每道题都是学习的机会。', '[{\"id\": 1, \"text\": \"谨慎对待\", \"is_correct\": true, \"description\": \"可能是钓鱼链接或恶意网站\", \"is_selected\": true}, {\"id\": 2, \"text\": \"立即点击\", \"is_correct\": false, \"description\": \"尽快了解谣言内容\", \"is_selected\": false}, {\"id\": 3, \"text\": \"转发分享\", \"is_correct\": false, \"description\": \"让更多人知道\", \"is_selected\": false}]', 1, '2025-10-10 23:35:06');
