INSERT INTO `protection_drill_question_details` VALUES (165, 29, 24, '账号盗用风险', '这种短信存在什么风险？', 1, '钓鱼攻击', 1, '钓鱼攻击', 1, 10, '冒充银行盗取账号信息', '冒充银行发送虚假短信，诱导用户点击恶意链接盗取账号信息。', '继续加油！每道题都是学习的机会。', '[{\"id\": 1, \"text\": \"钓鱼攻击\", \"is_correct\": true, \"description\": \"冒充银行盗取账号信息\", \"is_selected\": true}, {\"id\": 2, \"text\": \"银行通知\", \"is_correct\": false, \"description\": \"银行的正常通知\", \"is_selected\": false}, {\"id\": 3, \"text\": \"系统维护\", \"is_correct\": false, \"description\": \"银行系统维护通知\", \"is_selected\": false}]', 3, '2025-10-10 23:35:06');
