INSERT INTO `protection_drill_reports` VALUES (30, 6, '网络安全防护', '识别网络交往中的风险和陷阱', 8, 8, 100.00, 10, '{\"final_result\":{\"totalScore\":80,\"correctAnswers\":6,\"totalQuestions\":8,\"accuracy\":75,\"skillsMastery\":[{\"name\":\"风险识别\",\"score\":80,\"feedback\":\"能较好地识别常见风险信号\"},{\"name\":\"应对策略\",\"score\":70,\"feedback\":\"需要加强应对技巧的练习\"}],\"improvements\":[{\"area\":\"边界设定\",\"description\":\"需要更清楚地设定个人边界\",\"actions\":[\"练习表达拒绝\",\"明确个人底线\"]}]},\"question_analysis\":[{\"question_id\":30,\"question_title\":\"网络借贷风险\",\"question_text\":\"这种借贷存在什么风险？\",\"is_correct\":true,\"selected_option\":\"高利贷陷阱\",\"selected_option_id\":1,\"correct_option\":\"高利贷陷阱\",\"correct_option_id\":1,\"explanation\":\"隐藏高额利息和费用\",\"risk_explanation\":\"网络借贷往往隐藏高额费用和利息，日息0.05%年化利率超过18%。\",\"score_gained\":10,\"options\":[{\"id\":1,\"text\":\"高利贷陷阱\",\"description\":\"隐藏高额利息和费用\",\"is_selected\":true,\"is_correct\":true},{\"id\":2,\"text\":\"便民服务\",\"description\":\"便民的金融服务\",\"is_selected\":false,\"is_correct\":false},{\"id\":3,\"text\":\"优惠贷款\",\"description\":\"优惠的贷款产品\",\"is_selected\":false,\"is_correct\":false}]},{\"question_id\":31,\"question_title\":\"网络交友骗局\",\"question_text\":\"这种情况最可能是什么？\",\"is_correct\":true,\"selected_option\":\"杀猪盘诈骗\",\"selected_option_id\":1,\"correct_option\":\"杀猪盘诈骗\",\"correct_option_id\":1,\"explanation\":\"长期培养感情后实施诈骗\",\"risk_explanation\":\"诈骗分子长期培养感情关系，然后以各种理由要求转账。\",\"score_gained\":10,\"options\":[{\"id\":1,\"text\":\"杀猪盘诈骗\",\"description\":\"长期培养感情后实施诈骗\",\"is_selected\":true,\"is_correct\":true},{\"id\":2,\"text\":\"真实恋情\",\"description\":\"真实的跨国恋情\",\"is_selected\":false,\"is_correct\":false},{\"id\":3,\"text\":\"商业合作\",\"description\":\"商业投资机会\",\"is_selected\":false,\"is_correct\":false}]},{\"question_id\":32,\"question_title\":\"网络购物陷阱二\",\"question_text\":\"这种销售方式存在什么风险？\",\"is_correct\":true,\"selected_option\":\"虚假促销\",\"selected_option_id\":1,\"correct_option\":\"虚假促销\",\"correct_option_id\":1,\"explanation\":\"制造紧迫感诱导购买\",\"risk_explanati