INSERT INTO `tree_hole_whispers` VALUES (187, 6, '阳光明媚', '今天的阳光特别好，决定出去走走。看到路边开着的小花，心情也跟着明媚起来了。', 'very_happy', '[\"阳光\", \"散步\", \"花朵\"]', 0, NULL, NULL, 8, 0, '2025-10-01 12:26:57', '2025-10-03 12:39:00', 0);
